            expect(src).not.toMatch(/nucleiDrift !== 0/);
            expect(src).not.toMatch(/paletteDrift !== 0/);
            expect(src).not.toMatch(/breathDepth !== 0/);
            expect(src).not.toMatch(/warpDrift !== 0/);
        }
    });
});

